       ('88468a53-f1bc-4c2b-866f-ec43f20f7bca', '2022-04-18 06:54:26.945', NULL, '2022-04-18 06:54:26.947071', NULL, NULL, 11949, 'Con đẻ còn sống của người hoạt động kháng chiến bị nhiễm chất độc hóa học có tỷ lệ tổn thương cơ thể từ 61% đến 80%', NULL, NULL, 1, 1, '974000', NULL, NULL, NULL, 11722, 26, false, 1, 'HH40', NULL),
